//! Finite validation tool using the original shipping normal Sim role; no executor replacement.
use mycity_core::{time_capacity::{Command as C,Registration,Unit},timeline::Command as T,transaction::{Action,Caller,Envelope,Resource},units::Money};
use mycity_headless::{sim_client::Client,sim_host::{Command,Event},normal_pool};
use mycity_storage::{CapacityPolicy,Store};
use serde_json::{json,Value};
use std::{fs,fs::OpenOptions,io::Write,path::{Path,PathBuf},time::Duration};
fn event(c:&mut Client,p:&Path)->Event{let e=c.next(Duration::from_secs(15)).unwrap();writeln!(OpenOptions::new().create(true).append(true).open(p.join("events.jsonl")).unwrap(),"{}",serde_json::to_string(&e).unwrap()).unwrap();e}
fn req(s:&Store,op:&mut u64,a:Action)->Envelope{let e=Envelope{world:1,branch:1,operation_id:*op,expected_revision:s.engine().unwrap().world().view().revision,actions:vec![a]};*op+=1;e}
fn apply(s:&mut Store,op:&mut u64,caller:Caller,a:Action){let e=req(s,op,a);assert!(s.execute(caller,e).unwrap().model.is_ok());}
fn copy(src:&Path,dst:&Path){fs::create_dir(dst).unwrap();for f in fs::read_dir(src).unwrap(){let f=f.unwrap();let p=dst.join(f.file_name());if f.file_type().unwrap().is_dir(){copy(&f.path(),&p)}else{fs::copy(f.path(),&p).unwrap();assert_eq!(fs::read(f.path()).unwrap(),fs::read(p).unwrap());}}}
fn remote(c:&mut Client,p:&Path,id:u64,s:&mut Store,op:&mut u64,a:Action)->Envelope{let e=req(s,op,a);c.submit(id,Command::Execute{envelope:e.clone()}).unwrap();let out=event(c,p);assert!(out.payload["Ok"]["model"].get("Ok").is_some(),"{out:?}");assert!(s.execute(Caller::System,e.clone()).unwrap().model.is_ok());e}
fn facts(s:&Store)->Value{let mut v=serde_json::to_value(s.engine().unwrap().world().view()).unwrap();v.as_object_mut().unwrap().remove("revision");v}
fn actual(s:&Store)->u32{s.engine().unwrap().resources().iter().find(|r|r.id==701).unwrap().occupied}
fn main(){let args:Vec<_>=std::env::args().collect();let p=PathBuf::from(&args[1]);let exe=PathBuf::from(&args[2]);let poolroot=PathBuf::from(&args[3]);let rules=format!("sim-w3:{}",args[4]);fs::create_dir(&p).unwrap();let world=p.join("world");
 let mut s=Store::create_spatial(&world,&fs::read(&args[5]).unwrap(),vec![Resource::new(701,2).unwrap()],&rules,&fs::read(&args[6]).unwrap(),&fs::read(&args[7]).unwrap()).unwrap();let mut op=1;
 apply(&mut s,&mut op,Caller::System,Action::Timeline{command:T::Enable});for(id,n,due)in[(1,17,3600),(2,137,5000)]{apply(&mut s,&mut op,Caller::System,Action::Timeline{command:T::Lend{id,lender:3,borrower:4,principal:Money::new(n).unwrap(),due}});}
 apply(&mut s,&mut op,Caller::System,Action::TimeCapacity{command:C::Register{registration:Registration{canonical:70001,resource:701,aliases:[Some(1001),Some(1002),None,None],unit:Unit::Count,owner:1,operator:3,nominal_capacity:2,effective_capacity:2,identity_version:1,policy_version:1,open:true}}});
 apply(&mut s,&mut op,Caller::Account(3),Action::TimeCapacity{command:C::Reserve{alias:1001,account:3,consumer:301,consumer_version:1,start:0,end:10000,units:2}});let token=s.engine().unwrap().leases().iter().flatten().next().unwrap().token;
 apply(&mut s,&mut op,Caller::System,Action::TimeCapacity{command:C::Enter{token,occurred_at:0}});apply(&mut s,&mut op,Caller::System,Action::Timeline{command:T::Advance{target:7200,limit:32}});let before=s.engine().unwrap().timeline().unwrap().progress;assert_eq!(before.last_complete,3600);assert_eq!(before.target,Some(7200));assert!(before.phase.is_none());assert!(s.continuation_status().unwrap().is_none());s.checkpoint().unwrap();let used=s.capacity_status().unwrap().used_bytes;s.reduce_capacity_policy(CapacityPolicy{total_bytes:used+2*1024*1024,emergency_bytes:2*1024*1024+used/2}).unwrap();assert!(s.capacity_status().unwrap().normal_blocked);let original_facts=facts(&s);drop(s);copy(&world,&p.join("reference"));let mut reference=Store::open(&p.join("reference"),&rules).unwrap();
 let mut pool=normal_pool::Process::spawn(&exe,&poolroot,Some(&p.join("pool-heaps.jsonl"))).unwrap();let mut observations=Vec::new();let mut c=Client::new();c.start_in_pool(&exe,&world,false,false,&poolroot).unwrap();let ready=event(&mut c,&p);assert_eq!(ready.kind,"ready");observations.push(serde_json::to_value(ready).unwrap());
 let cancel=remote(&mut c,&p,1,&mut reference,&mut op,Action::Timeline{command:T::CancelAdvance});assert_eq!(facts(&reference),original_facts);assert_eq!(actual(&reference),2);assert!(reference.engine().unwrap().timeline().unwrap().progress.target.is_none());c.submit(2,Command::Status).unwrap();observations.push(serde_json::to_value(event(&mut c,&p)).unwrap());c.stop().unwrap();
 let mut cold=Store::open(&world,&rules).unwrap();assert_eq!(cold.state_hash().unwrap(),reference.state_hash().unwrap());assert_eq!(cold.engine().unwrap().export_checkpoint().unwrap(),reference.engine().unwrap().export_checkpoint().unwrap());assert_eq!(facts(&cold),original_facts);let hash=cold.state_hash().unwrap();let seq=cold.committed_sequence();assert!(cold.execute(Caller::System,cancel.clone()).unwrap().model.is_ok());assert_eq!(cold.state_hash().unwrap(),hash);assert_eq!(cold.committed_sequence(),seq);assert!(cold.continuation_status().unwrap().is_none());drop(cold);
 c=Client::new();c.start_in_pool(&exe,&world,false,false,&poolroot).unwrap();let ready=event(&mut c,&p);assert_eq!(ready.kind,"ready");observations.push(serde_json::to_value(ready).unwrap());let exit=remote(&mut c,&p,10,&mut reference,&mut op,Action::TimeCapacity{command:C::Exit{token,occurred_at:3600}});c.submit(11,Command::Status).unwrap();observations.push(serde_json::to_value(event(&mut c,&p)).unwrap());c.stop().unwrap();
 for e in &observations{let v=e["payload"].get("Ok").unwrap_or(&e["payload"]);let a=&v["runtime"]["allocator_boundary"]["snapshot"];assert_eq!(a["activation"]["grant_bytes"],59*1024*1024);assert_eq!(a["allocation_failures"],0);assert!(a["arena_used_bytes"].as_u64().unwrap()<=a["arena_usable_bytes"].as_u64().unwrap());}
 let balance=normal_pool::status(&poolroot).unwrap();assert_eq!(balance.workspace_grants,2);assert_eq!(balance.workspace_returns,2);assert_eq!(balance.available_touched_bytes,64*1024*1024);pool.finish().unwrap();let mut cold=Store::open(&world,&rules).unwrap();assert_eq!(cold.state_hash().unwrap(),reference.state_hash().unwrap());assert_eq!(cold.engine().unwrap().export_checkpoint().unwrap(),reference.engine().unwrap().export_checkpoint().unwrap());assert_eq!(actual(&cold),0);let hash=cold.state_hash().unwrap();let seq=cold.committed_sequence();for e in[exit,cancel]{assert!(cold.execute(Caller::System,e).unwrap().model.is_ok());}assert_eq!(cold.state_hash().unwrap(),hash);assert_eq!(cold.committed_sequence(),seq);let t=cold.engine().unwrap().timeline().unwrap();assert_eq!(t.progress.last_complete,3600);assert!(t.progress.target.is_none());assert_eq!(t.claims[0].paid.value(),17);assert_eq!(t.claims[1].principal.value(),137);assert_eq!(t.claims[1].paid.value(),0);
 fs::write(p.join("role-observations.json"),serde_json::to_vec_pretty(&observations).unwrap()).unwrap();fs::write(p.join("pool-return.json"),serde_json::to_vec_pretty(&balance).unwrap()).unwrap();fs::write(p.join("result.json"),serde_json::to_vec_pretty(&json!({"same_complete_direct_reference":true,"original_cancel_and_exit_replayed_once":true,"already_paid17_and_future137_preserved":true,"actual_after_explicit_exit":actual(&cold),"engine_owned_bytes":cold.engine().unwrap().owned_capacity_bytes(),"store_owned_bytes":cold.owned_capacity_bytes().unwrap(),"capacity":cold.capacity_status().unwrap(),"reference_and_creator_are_outside_shipping_role_test_tool_cost":true,"not_whole_game_native16GB_speed_M0_or_GPU_acceptance":true})).unwrap()).unwrap();
}
